from copy import deepcopy

def _build_schema_map(schema_columns):
    """
    建立 {lower_name: original_name} 映射。
    如存在仅大小写不同的重复列，会抛错以避免歧义。
    """
    mapping = {}
    for col in schema_columns:
        key = col.lower()
        if key in mapping and mapping[key] != col:
            raise ValueError(f"Schema contains conflicting columns by case: {mapping[key]} vs {col}")
        mapping[key] = col
    return mapping

def _remap_col(col, schema_map, alias_set):
    """
    若是别名，保持原样；若在 schema_map 中（大小写不敏感），返回原始大小写；否则返回原值。
    """
    if col in alias_set:
        return col
    return schema_map.get(col.lower(), col)

def _collect_declared_aliases(plan):
    declared = set()
    for a in plan.get("vertical_aggregations", []):
        if "alias" in a:
            declared.add(a["alias"])
    for r in plan.get("row_aggregations", []):
        if "alias" in r:
            declared.add(r["alias"])
    return declared

def validate_plan(plan, schema_columns):
    schema_map = _build_schema_map(schema_columns)              # {lower: original}
    declared_aliases = _collect_declared_aliases(plan)

    used_columns = []

    # Extract used columns
    for f in plan.get("filters", []):
        used_columns.append(f["column"])

    for a in plan.get("vertical_aggregations", []):
        used_columns.append(a["column"])
        used_columns += a.get("group_by", [])

    for r in plan.get("row_aggregations", []):
        # 按你的注释，这是类别标签而非 schema 字段；如果确实需要验证可改为 extend
        used_columns.extend(r["column"])

    if "sort" in plan:
        used_columns.append(plan["sort"]["by"])

    # 计算无效列（考虑别名及大小写不敏感的 schema 匹配）
    invalid = []
    for col in used_columns:
        if (col in declared_aliases) or (col.lower() in schema_map):
            continue
        invalid.append(col)

    if invalid:
        return {"valid": False, "hallucinated_columns": invalid}

    # 生成大小写修正后的 plan（把命中的列替换回 schema 的原始大小写）
    fixed = deepcopy(plan)

    # filters
    for f in fixed.get("filters", []):
        f["column"] = _remap_col(f["column"], schema_map, declared_aliases)

    # vertical_aggregations
    for a in fixed.get("vertical_aggregations", []):
        a["column"] = _remap_col(a["column"], schema_map, declared_aliases)
        if "group_by" in a and isinstance(a["group_by"], list):
            a["group_by"] = [
                _remap_col(g, schema_map, declared_aliases) for g in a["group_by"]
            ]

    # row_aggregations: 你的注释说这些是类别标签，不是 schema 字段，这里不做映射
    # 如果你希望它们也参与映射，把下面注释放开：
    for r in fixed.get("row_aggregations", []):
        if "column" in r and isinstance(r["column"], list):
            r["column"] = [
                _remap_col(c, schema_map, declared_aliases) for c in r["column"]
            ]

    # sort
    if "sort" in fixed and "by" in fixed["sort"]:
        fixed["sort"]["by"] = _remap_col(fixed["sort"]["by"], schema_map, declared_aliases)

    return {"valid": True, "outcome": fixed}


# ===== 调用部分保持原样 =====
arr = _('Get AR Schema').first()['json']['schema'].to_py()
arr_columns = [dic['column'] for dic in arr]

plan = _input.first()['json']['output'].to_py()
dic = validate_plan(plan, arr_columns)
return dic

