import pandas as pd

def apply_row_aggregations(df: pd.DataFrame, plan: dict) -> pd.DataFrame:
    for agg in plan.get("row_aggregations", []):
        cols = agg["column"]
        op = agg["operation"]
        alias = agg["alias"]
        if op == "sum":
            df[alias] = df[cols].sum(axis=1)
        elif op == "avg":
            df[alias] = df[cols].mean(axis=1)
        elif op == "min":
            df[alias] = df[cols].min(axis=1)
        elif op == "max":
            df[alias] = df[cols].max(axis=1)
        else:
            raise ValueError(f"Unsupported row-wise operation: {op}")
    return df

def apply_vertical_aggregations(df: pd.DataFrame, plan: dict) -> pd.DataFrame:
    all_vert_results = []
    for agg in plan.get("vertical_aggregations", []):
        col = agg["column"]
        op = agg["operation"]
        alias = agg["alias"]
        group_by = agg.get("group_by")

        if group_by:
            grouped = df.groupby(group_by, as_index=False)
            agg_df = grouped.agg({col: op}).rename(columns={col: alias})
        else:
            agg_val = getattr(df[col], op)()
            agg_df = pd.DataFrame([{alias: agg_val}])
        all_vert_results.append(agg_df)

    if all_vert_results:
        from functools import reduce
        def merge_fn(left, right):
            common = list(set(left.columns) & set(right.columns))
            if common:
                return pd.merge(left, right, on=common)
            else:
                return pd.concat([left, right], axis=1)
        return reduce(merge_fn, all_vert_results)
    else:
        return df

def apply_filter_group_aggregate(df: pd.DataFrame, plan: dict) -> pd.DataFrame:
    df = df.copy()

    # 1. Apply filters
    for f in plan.get("filters", []):
        col, op, val = f["column"], f["operator"], f["value"]
        if op == "==":
            df = df[df[col] == val]
        elif op == "!=":
            df = df[df[col] != val]
        elif op == ">":
            df = df[df[col] > val]
        elif op == "<":
            df = df[df[col] < val]
        elif op == ">=":
            df = df[df[col] >= val]
        elif op == "<=":
            df = df[df[col] <= val]
        elif op == "in":
            df = df[df[col].isin(val)]
        elif op == "not in":
            df = df[~df[col].isin(val)]

    result = df

    # Determine aggregation order
    agg_order = plan.get("aggregation_order", ["row", "vertical"])

    result = df

    for step in agg_order:
        if step == "row":
            result = apply_row_aggregations(result, plan)
        elif step == "vertical":
            result = apply_vertical_aggregations(result, plan)
        else:
            raise ValueError(f"Unknown aggregation step: {step}")

    # 4. Apply sorting
    sort_plan = plan.get("sort")
    if sort_plan:
        by = sort_plan["by"]
        ascending = sort_plan.get("order", "asc") == "asc"
        result = result.sort_values(by=by, ascending=ascending)

    # 5. Apply limit
    limit = plan.get("limit")
    if isinstance(limit, int) and limit > 0:
        result = result.head(limit)

    return result


arr = _('Data array').first()['json']['arr'].to_py()
df = pd.DataFrame(arr)
filter_plan = _input.first()['json']['outcome'].to_py()

result = apply_filter_group_aggregate(df, filter_plan)
output = result.to_dict(orient='records')


return [
        {
        "json": {
          "table": output
        }
        }
      ];
